import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const MovieList = () => {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    fetchMovies();
  }, []);

  const fetchMovies = async () => {
    try {
      const response = await fetch('http://localhost:8080/api/movies');
      const data = await response.json();
      setMovies(data);
    } catch (error) {
      console.error('Error fetching movies:', error);
    } finally {
      setLoading(false);
    }
  };

  // Simple search filter
  const filteredMovies = movies.filter(movie =>
    movie.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleBookMovie = (movie) => {
    navigate(`/booking/${movie.movieId}`);
  };

  if (loading) {
    return (
      <div style={{ textAlign: 'center', padding: '50px' }}>
        <p>Loading movies...</p>
      </div>
    );
  }

  return (
    <div style={{ padding: '20px', background: '#f5f5f5', minHeight: '100vh' }}>
      {/* Header */}
      <div style={{ textAlign: 'center', marginBottom: '40px' }}>
        <h1 style={{ fontSize: '2.5rem', color: '#333', marginBottom: '10px' }}>
          🎬 CINEMA EXPERIENCE
        </h1>
        <p style={{ color: '#666', fontSize: '1.1rem' }}>
          Book tickets for the latest blockbuster movies
        </p>
      </div>
      
      {/* Simple Search Bar */}
      <div style={{ maxWidth: '600px', margin: '0 auto 40px auto' }}>
        <input
          type="text"
          placeholder="Search movies by title..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            width: '100%',
            padding: '15px',
            fontSize: '16px',
            border: '2px solid #ddd',
            borderRadius: '10px',
            outline: 'none',
            boxShadow: '0 2px 5px rgba(0,0,0,0.1)'
          }}
        />
      </div>

      {/* Movies Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(350px, 1fr))', gap: '30px', maxWidth: '1200px', margin: '0 auto' }}>
        {filteredMovies.map(movie => (
          <div key={movie.movieId} style={{ 
            background: 'white', 
            borderRadius: '15px', 
            overflow: 'hidden', 
            boxShadow: '0 5px 20px rgba(0,0,0,0.1)',
            transition: 'transform 0.3s ease'
          }}>
            {/* Movie Poster */}
            <div style={{ height: '200px', background: '#f0f0f0', position: 'relative' }}>
              {movie.posterUrl ? (
                <img 
                  src={movie.posterUrl} 
                  alt={movie.title}
                  style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                />
              ) : (
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', fontSize: '3rem' }}>
                  🎬
                </div>
              )}
              <div style={{
                position: 'absolute',
                top: '10px',
                right: '10px',
                background: '#ff6b6b',
                color: 'white',
                padding: '5px 10px',
                borderRadius: '20px',
                fontSize: '12px',
                fontWeight: 'bold'
              }}>
                NEW
              </div>
            </div>
            
            {/* Movie Info */}
            <div style={{ padding: '20px' }}>
              <h3 style={{ fontSize: '1.3rem', marginBottom: '10px', color: '#333' }}>{movie.title}</h3>
              <p style={{ color: '#666', marginBottom: '15px', fontSize: '0.9rem', lineHeight: '1.4' }}>
                {movie.description}
              </p>
              
              {/* Movie Meta */}
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '15px', fontSize: '0.9rem' }}>
                <span style={{ background: '#e3f2fd', color: '#1976d2', padding: '3px 8px', borderRadius: '12px' }}>
                  {movie.genre}
                </span>
                <span style={{ color: '#ffa500' }}>
                  ⭐ {movie.rating}
                </span>
                <span style={{ color: '#4caf50', fontWeight: 'bold' }}>
                  ₹{movie.price}
                </span>
              </div>
              
              {/* Book Button */}
              <button 
                onClick={() => handleBookMovie(movie)}
                style={{
                  width: '100%',
                  padding: '12px',
                  background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                  color: 'white',
                  border: 'none',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontSize: '16px',
                  fontWeight: 'bold',
                  transition: 'transform 0.2s ease'
                }}
                onMouseOver={(e) => e.target.style.transform = 'translateY(-2px)'}
                onMouseOut={(e) => e.target.style.transform = 'translateY(0)'}
              >
                🎫 Book Tickets
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* No Results Message */}
      {filteredMovies.length === 0 && (
        <div style={{ textAlign: 'center', padding: '60px 20px' }}>
          <h2 style={{ color: '#666', marginBottom: '10px' }}>No movies found</h2>
          <p style={{ color: '#999' }}>No movies matching "{searchTerm}"</p>
          <button 
            onClick={() => setSearchTerm('')}
            style={{
              padding: '10px 20px',
              background: '#667eea',
              color: 'white',
              border: 'none',
              borderRadius: '5px',
              cursor: 'pointer',
              marginTop: '15px'
            }}
          >
            Clear Search
          </button>
        </div>
      )}
    </div>
  );
};

export default MovieList;
